    "jsCode": "\nconst CFG = {\"messaging\":{\"mode\":\"twilio\",\"provider\":\"twilio\",\"twilio\":{\"accountSid\":\"AC00000000000000000000000000000000\",\"from\":\"+61491570006\",\"messagingServiceSid\":null,\"credential\":{\"id\":\"ZZExampleTwilio1\",\"name\":\"ZZ example Twilio API key\"},\"inboundAuth\":\"signature\",\"signatureVariable\":\"LITE_TWILIO_AUTH_TOKEN\",\"inboundCredential\":null,\"allowedRecipients\":[\"+61491570156\",\"+61491570157\",\"+61491570158\",\"+61491570159\",\"+61491570110\"],\"allowAllRecipients\":false}}};\nconst clean = (s) => String(s == null ? '' : s).trim();\nconst normPhone = (s) => { let d = clean(s).replace(/[^0-9+]/g, ''); if (d.startsWith('+61')) d = '0' + d.slice(3); d = d.replace(/[^0-9]/g, ''); return /^0[2-478][0-9]{8}$/.test(d) ? d : ''; };\n/** Australian national number (04xx xxx xxx) to E.164 (+614xxxxxxxx), as Twilio needs it. */\nconst toE164 = (s) => { const n = normPhone(s); return n ? '+61' + n.slice(1) : ''; };\n\nif (!$('Plan Health').isExecuted) return [{ json: { none: true } }];\nconst h = $('Plan Health').first().json;\nif (!h.retries.length || CFG.messaging.mode !== 'twilio') return [{ json: { none: true } }];\nconst API = 'https://api.twilio.com/2010-04-01/Accounts/' + CFG.messaging.twilio.accountSid;\n// Before any resend, ask Twilio: by Message SID when there is one, else by recipient (a timeout leaves no SID). No\n// DateSent filter: a message Twilio still has queued has no send date yet, and must count as found.\nreturn h.retries.map((r) => { const f = r.fields; const sid = clean(f['Provider Message ID']);\n  return { json: { id: r.id, checkUrl: /^(SM|MM)[0-9a-f]{32}$/.test(sid) ? API + '/Messages/' + sid + '.json'\n    : API + '/Messages.json?To=' + encodeURIComponent(toE164(f.To)) + '&PageSize=50' } }; });"
